<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Connection, Delete, Refresh, Setting, Warning } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, apiErrorMessage, ensureCsrf } from '../services/api'
import { authStore } from '../stores/auth'
import type { AutoReplyAttempt, AutoReplyAttemptStatus, AutoReplyPolicy, BrowserDevice } from '../types'

type RuntimeState = 'RUNNING'|'REVIEW'|'PAUSED'|'OFFLINE'|'DISABLED'|'ERROR'
const policies=ref<AutoReplyPolicy[]>([]),attempts=ref<AutoReplyAttempt[]>([]),devices=ref<BrowserDevice[]>([])
const loading=ref(true),saving=ref(false),errorMessage=ref(''),dialogOpen=ref(false),editing=ref<AutoReplyPolicy>()
const activeTab=ref('overview'),attemptStatusFilter=ref(''),attemptAccountFilter=ref('')
const canManage=computed(()=>authStore.state.user?.role!=='RECRUITER')
const form=reactive({enabled:false,autoSendEnabled:false,responseTimeoutMinutes:120,dailyLimit:20,minimumIntervalSeconds:180,sendingWindowStart:'09:00:00',sendingWindowEnd:'21:00:00',timezone:'Asia/Shanghai',maxConsecutiveFailures:3,replyTemplate:''})
const statusLabels:Record<AutoReplyAttemptStatus,string>={CLAIMED:'处理中',PENDING_REVIEW:'待人工审核',SENT:'已发送',FAILED:'失败',SKIPPED:'已跳过'}
const runtimeMeta:Record<RuntimeState,{label:string,type:'success'|'warning'|'danger'|'info'}>={RUNNING:{label:'自动运行中',type:'success'},REVIEW:{label:'等待人工审核',type:'warning'},PAUSED:{label:'安全暂停',type:'danger'},OFFLINE:{label:'设备未在线',type:'danger'},DISABLED:{label:'策略未启用',type:'info'},ERROR:{label:'账号能力异常',type:'danger'}}
function activeDevice(id:string){return devices.value.find(x=>x.accountId===id&&x.status==='ACTIVE')}
function accountReady(x:AutoReplyPolicy){return x.accountStatus==='ACTIVE'&&x.messageSendCapable}
function runtimeState(x:AutoReplyPolicy):RuntimeState{if(!x.enabled)return'DISABLED';if(!accountReady(x))return'ERROR';if(x.pausedUntil&&new Date(x.pausedUntil)>new Date())return'PAUSED';const d=activeDevice(x.accountId);if(!d||['OFFLINE','DISABLED'].includes(d.runtimeState))return'OFFLINE';if(d.runtimeState==='PAUSED')return'PAUSED';return x.autoSendEnabled?'RUNNING':'REVIEW'}
const runtimeAccounts=computed(()=>policies.value.map(policy=>({policy,state:runtimeState(policy),device:activeDevice(policy.accountId)})))
const attentionAccounts=computed(()=>runtimeAccounts.value.filter(x=>['PAUSED','OFFLINE','ERROR'].includes(x.state)))
const stats=computed(()=>({total:policies.value.length,running:runtimeAccounts.value.filter(x=>x.state==='RUNNING').length,attention:attentionAccounts.value.length,sentToday:policies.value.reduce((n,x)=>n+x.sentToday,0),online:devices.value.filter(x=>x.status==='ACTIVE'&&x.runtimeState==='RUNNING').length}))
const filteredAttempts=computed(()=>attempts.value.filter(x=>(!attemptStatusFilter.value||x.status===attemptStatusFilter.value)&&(!attemptAccountFilter.value||x.accountId===attemptAccountFilter.value)))
async function load(){loading.value=true;errorMessage.value='';try{const [p,a,d]=await Promise.all([api.get<AutoReplyPolicy[]>('/auto-replies/policies'),api.get<AutoReplyAttempt[]>('/auto-replies/attempts'),api.get<BrowserDevice[]>('/browser-devices')]);policies.value=p.data;attempts.value=a.data;devices.value=d.data}catch(e){errorMessage.value=apiErrorMessage(e,'自动跟进配置加载失败')}finally{loading.value=false}}
function openPolicy(x:AutoReplyPolicy){editing.value=x;Object.assign(form,{enabled:x.enabled,autoSendEnabled:x.autoSendEnabled,responseTimeoutMinutes:x.responseTimeoutMinutes,dailyLimit:x.dailyLimit,minimumIntervalSeconds:x.minimumIntervalSeconds,sendingWindowStart:x.sendingWindowStart,sendingWindowEnd:x.sendingWindowEnd,timezone:x.timezone,maxConsecutiveFailures:x.maxConsecutiveFailures,replyTemplate:x.replyTemplate});dialogOpen.value=true}
async function save(){if(!editing.value)return;if(form.autoSendEnabled&&!form.enabled){ElMessage.error('开启自动发送前必须启用策略');return}saving.value=true;try{await ensureCsrf();await api.put(`/auto-replies/policies/${editing.value.accountId}`,form);ElMessage.success('账号自动跟进策略已保存');dialogOpen.value=false;await load()}catch(e){ElMessage.error(apiErrorMessage(e,'策略保存失败'))}finally{saving.value=false}}
function formatDate(v?:string){return v?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—'}
function attemptType(s:AutoReplyAttemptStatus){return s==='SENT'?'success':s==='FAILED'?'danger':s==='SKIPPED'?'info':'warning'}
function quota(x:AutoReplyPolicy){return Math.min(100,Math.round(x.sentToday/Math.max(x.dailyLimit,1)*100))}
function deviceLabel(d?:BrowserDevice){return d?.runtimeState==='RUNNING'?'在线运行':d?.runtimeState==='PAUSED'?'已暂停':d?'离线':'未配对'}
async function createPairing(accountId:string){try{await ensureCsrf();const {data}=await api.post<{pairingToken:string}>('/browser-devices/pairings',{accountId});await ElMessageBox.alert(`配对令牌：${data.pairingToken}\n\n10 分钟内在 Chrome 扩展设置中输入。关闭后不再展示。`,'一次性浏览器配对令牌',{confirmButtonText:'我已安全保存'});await load()}catch(e){ElMessage.error(apiErrorMessage(e,'创建配对令牌失败'))}}
async function revokeDevice(d:BrowserDevice){try{await ElMessageBox.confirm(`撤销 ${d.displayName}？扩展将立即无法同步或发送。`,'撤销浏览器设备',{type:'warning'});await ensureCsrf();await api.delete(`/browser-devices/${d.id}`);ElMessage.success('设备已撤销');await load()}catch(e){if(e!=='cancel')ElMessage.error(apiErrorMessage(e,'撤销失败'))}}
onMounted(load)
</script>

<template><div class="page-shell auto-page">
  <header class="page-heading"><div><span class="eyebrow">AUTOMATED FOLLOW-UP</span><h1>多账号自动跟进</h1><p>统一观察回复链路、账号风险与发送结果，只在满足超时、频率、时段和设备在线条件后执行。</p></div><el-button :icon="Refresh" :loading="loading" @click="load">刷新状态</el-button></header>
  <el-alert class="safety-alert" type="warning" :closable="false" show-icon title="网页伴随端存在平台限制风险。遇到验证码、登录失效或页面结构变化立即暂停，不导出 Cookie、不绕过平台风控。"/>
  <div v-if="loading" class="surface-panel"><el-skeleton :rows="8" animated/></div>
  <div v-else-if="errorMessage" class="surface-panel error-state"><el-icon><Warning/></el-icon><strong>自动跟进状态暂时无法加载</strong><span>{{errorMessage}}</span><el-button @click="load">重试</el-button></div>
  <template v-else>
    <nav class="module-nav"><button v-for="t in [{id:'overview',name:'运行总览',desc:'健康与待办'},{id:'accounts',name:'账号策略',desc:'触发与限流'},{id:'devices',name:'浏览器设备',desc:'连接与诊断'},{id:'attempts',name:'发送记录',desc:'结果与追踪'}]" :key="t.id" :class="{active:activeTab===t.id}" @click="activeTab=t.id"><strong>{{t.name}}</strong><span>{{t.desc}}</span></button></nav>
    <template v-if="activeTab==='overview'">
      <div class="metrics"><article><span>自动运行账号</span><strong>{{stats.running}}<small> / {{stats.total}}</small></strong></article><article><span>需要关注</span><strong :class="{danger:stats.attention}">{{stats.attention}}</strong></article><article><span>今日已发送</span><strong>{{stats.sentToday}}</strong></article><article><span>在线浏览器</span><strong>{{stats.online}}</strong></article></div>
      <div class="overview-grid"><section class="surface-panel"><div class="section-title-row"><div><h2>账号运行状态</h2><p>先处理红色异常，再开启自动发送。</p></div><el-button text @click="activeTab='accounts'">管理策略</el-button></div><div v-if="!runtimeAccounts.length" class="empty">还没有可管理的招聘账号</div><article v-for="x in runtimeAccounts" :key="x.policy.accountId" class="health-row"><i>{{x.policy.accountName.slice(0,1)}}</i><div class="identity"><strong>{{x.policy.accountName}}</strong><span>{{x.policy.companyName}}</span></div><el-tag :type="runtimeMeta[x.state].type">{{runtimeMeta[x.state].label}}</el-tag><div class="quota"><span>今日额度 {{x.policy.sentToday}}/{{x.policy.dailyLimit}}</span><el-progress :percentage="quota(x.policy)" :show-text="false" :stroke-width="6"/></div><el-button v-if="canManage" text @click="openPolicy(x.policy)">配置</el-button></article></section>
      <aside class="surface-panel"><div class="section-title-row"><div><h2>需要处理</h2><p>{{attentionAccounts.length?'以下问题会阻止自动发送':'当前没有阻断项'}}</p></div></div><div v-if="!attentionAccounts.length" class="all-good"><b>✓</b><strong>链路状态正常</strong><small>仍会遵守限流与发送窗口</small></div><button v-for="x in attentionAccounts" :key="x.policy.accountId" class="attention" @click="activeTab=x.state==='OFFLINE'?'devices':'accounts'"><b></b><span><strong>{{x.policy.accountName}} · {{runtimeMeta[x.state].label}}</strong><small>{{x.device?.stopReason||'请检查账号能力、扩展登录和心跳状态'}}</small></span><em>处理 →</em></button></aside></div>
      <section class="surface-panel flow-panel"><div class="section-title-row"><div><h2>一次自动回复如何完成</h2><p>后端规则与发送租约是唯一权威，浏览器扩展只执行已授权任务。</p></div></div><div class="flow"><article v-for="(x,i) in [['识别新消息','只采集必要会话状态'],['校验超时与规则','人工已回复则立即跳过'],['签发单次发送租约','检查时段、间隔与额度'],['页面发送并回执','DOM 异常或验证码停机']]" :key="i"><b>{{i+1}}</b><div><strong>{{x[0]}}</strong><span>{{x[1]}}</span></div></article></div></section>
    </template>
    <section v-else-if="activeTab==='accounts'" class="surface-panel"><div class="section-title-row"><div><h2>账号独立策略</h2><p>建议先以人工审核观察，再按账号逐步开启自动发送。</p></div></div><div class="card-grid"><article v-for="x in policies" :key="x.accountId"><header><div class="identity"><strong>{{x.accountName}}</strong><span>{{x.companyName}}</span></div><el-tag :type="runtimeMeta[runtimeState(x)].type">{{runtimeMeta[runtimeState(x)].label}}</el-tag></header><div class="mode"><strong>{{x.autoSendEnabled?'自动发送':'人工审核'}}</strong><span>{{x.responseTimeoutMinutes}} 分钟无人回复后触发</span></div><dl><div><dt>发送窗口</dt><dd>{{x.sendingWindowStart.slice(0,5)}}–{{x.sendingWindowEnd.slice(0,5)}}</dd></div><div><dt>最小间隔</dt><dd>{{x.minimumIntervalSeconds}} 秒</dd></div><div><dt>每日上限</dt><dd>{{x.sentToday}} / {{x.dailyLimit}}</dd></div><div><dt>失败暂停</dt><dd>{{x.consecutiveFailures}} / {{x.maxConsecutiveFailures}}</dd></div></dl><el-progress :percentage="quota(x)" :show-text="false"/><el-button v-if="canManage" :icon="Setting" :disabled="!x.messageSendCapable" @click="openPolicy(x)">配置此账号</el-button></article></div></section>
    <section v-else-if="activeTab==='devices'" class="surface-panel"><div class="section-title-row"><div><h2>浏览器伴随设备</h2><p>每个账号仅保留一台活跃设备；异常时必须人工介入。</p></div></div><div class="card-grid"><article v-for="x in policies" :key="x.accountId"><header><div class="identity"><strong>{{x.accountName}}</strong><span>{{x.companyName}}</span></div><el-tag :type="activeDevice(x.accountId)?.runtimeState==='RUNNING'?'success':'info'">{{deviceLabel(activeDevice(x.accountId))}}</el-tag></header><div v-if="activeDevice(x.accountId)" class="device"><Connection/><span><strong>{{activeDevice(x.accountId)?.displayName}}</strong><small>最后心跳 {{formatDate(activeDevice(x.accountId)?.lastHeartbeatAt)}}</small></span></div><div v-else class="unpaired">尚未配对 Chrome 扩展，无法检测消息或执行发送。</div><el-alert v-if="activeDevice(x.accountId)?.stopReason" type="warning" :closable="false" :title="activeDevice(x.accountId)?.stopReason"/><footer v-if="canManage"><el-button :icon="Connection" @click="createPairing(x.accountId)">{{activeDevice(x.accountId)?'重新配对':'生成配对令牌'}}</el-button><el-button v-if="activeDevice(x.accountId)" type="danger" plain :icon="Delete" @click="revokeDevice(activeDevice(x.accountId)!)">撤销</el-button></footer></article></div></section>
    <section v-else class="surface-panel"><div class="section-title-row attempts-head"><div><h2>发送记录</h2><p>查看每次发送租约结果，失败与跳过不计成功额度。</p></div><div class="filters"><el-select v-model="attemptAccountFilter" clearable placeholder="全部账号"><el-option v-for="x in policies" :key="x.accountId" :label="x.accountName" :value="x.accountId"/></el-select><el-select v-model="attemptStatusFilter" clearable placeholder="全部状态"><el-option v-for="(v,k) in statusLabels" :key="k" :label="v" :value="k"/></el-select></div></div><el-empty v-if="!filteredAttempts.length" :image-size="72" description="暂无符合条件的记录"/><div class="attempt-list"><article v-for="x in filteredAttempts" :key="x.id"><div class="identity"><strong>{{x.candidateName}}</strong><span>{{x.jobTitle}} · {{x.accountName}}</span></div><el-tag :type="attemptType(x.status)">{{statusLabels[x.status]}}</el-tag><div class="result"><strong>{{x.resultMessage||'等待处理结果'}}</strong><span>尝试 {{x.attemptCount}} 次 · {{formatDate(x.completedAt||x.createdAt)}}</span></div></article></div></section>
  </template>
  <el-dialog v-model="dialogOpen" :title="`${editing?.accountName??''} · 自动跟进策略`" width="720px"><el-alert type="info" :closable="false" show-icon title="建议先开启待审核草稿观察一周，再逐步开放自动发送。"/><el-form label-position="top" class="policy-form"><div class="form-grid"><el-form-item label="启用超时跟进"><el-switch v-model="form.enabled"/></el-form-item><el-form-item label="无需人工审核自动发送"><el-switch v-model="form.autoSendEnabled" :disabled="!form.enabled"/></el-form-item><el-form-item label="无人回复超时（分钟）"><el-input-number v-model="form.responseTimeoutMinutes" :min="5" :max="10080"/></el-form-item><el-form-item label="账号每日上限"><el-input-number v-model="form.dailyLimit" :min="1" :max="200"/></el-form-item><el-form-item label="最小处理间隔（秒）"><el-input-number v-model="form.minimumIntervalSeconds" :min="30" :max="86400"/></el-form-item><el-form-item label="连续失败暂停阈值"><el-input-number v-model="form.maxConsecutiveFailures" :min="1" :max="20"/></el-form-item><el-form-item label="发送窗口开始"><el-time-picker v-model="form.sendingWindowStart" value-format="HH:mm:ss" format="HH:mm"/></el-form-item><el-form-item label="发送窗口结束"><el-time-picker v-model="form.sendingWindowEnd" value-format="HH:mm:ss" format="HH:mm"/></el-form-item><el-form-item label="IANA 时区"><el-input v-model="form.timezone"/></el-form-item></div><el-form-item label="自动回复模板"><el-input v-model="form.replyTemplate" type="textarea" :rows="4" maxlength="1000" show-word-limit/><small class="hint">支持变量：{jobTitle}；不会将候选人原消息发送给生成模型。</small></el-form-item></el-form><template #footer><el-button @click="dialogOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存账号策略</el-button></template></el-dialog>
</div></template>

<style scoped>
.auto-page{max-width:1440px}.eyebrow{color:var(--primary);font-size:11px;font-weight:700;letter-spacing:.14em}.safety-alert,.module-nav,.metrics,.overview-grid,.flow-panel{margin-bottom:20px}.module-nav{display:grid;grid-template-columns:repeat(4,1fr);padding:5px;border:1px solid var(--border);border-radius:14px;background:var(--surface)}.module-nav button{display:grid;gap:2px;padding:11px 16px;border:0;border-radius:10px;background:transparent;color:var(--text-secondary);text-align:left;cursor:pointer}.module-nav strong{color:var(--text-primary)}.module-nav span{font-size:11px}.module-nav .active{background:var(--primary);box-shadow:0 4px 12px #2563eb2e}.module-nav .active>*{color:#fff}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.metrics article{padding:18px 20px;border:1px solid var(--border);border-radius:12px;background:var(--surface)}.metrics span,.identity span,.result span{display:block;color:var(--text-secondary);font-size:12px}.metrics strong{display:block;margin-top:6px;font-size:24px}.metrics small{font-size:14px;color:var(--text-secondary)}.danger{color:var(--danger)}.overview-grid{display:grid;grid-template-columns:1.6fr .8fr;gap:20px}.health-row{display:grid;grid-template-columns:38px minmax(140px,1fr) auto 160px auto;align-items:center;gap:14px;padding:14px 20px;border-top:1px solid var(--border)}.health-row i{display:grid;height:38px;place-items:center;border-radius:11px;background:var(--primary-soft);color:var(--primary);font-style:normal;font-weight:700}.quota>span{display:block;margin-bottom:6px;color:var(--text-secondary);font-size:12px}.all-good{display:grid;justify-items:center;gap:6px;padding:36px}.all-good b{display:grid;width:40px;height:40px;place-items:center;border-radius:50%;background:#ecfdf3;color:#16a34a}.all-good small{color:var(--text-secondary)}.attention{display:grid;width:100%;grid-template-columns:8px 1fr auto;align-items:center;gap:10px;padding:14px 20px;border:0;border-top:1px solid var(--border);background:transparent;text-align:left;cursor:pointer}.attention>b{width:7px;height:7px;border-radius:50%;background:var(--danger)}.attention small{display:block;margin-top:4px;color:var(--text-secondary)}.attention em{color:var(--primary);font-style:normal;font-size:12px}.flow{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;padding:0 20px 20px}.flow article{display:flex;gap:10px;padding:14px;border-radius:11px;background:var(--surface-muted)}.flow b{display:grid;flex:0 0 28px;height:28px;place-items:center;border-radius:8px;background:var(--primary);color:#fff}.flow span{display:block;margin-top:5px;color:var(--text-secondary);font-size:12px}.card-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;padding:0 20px 20px}.card-grid>article{padding:18px;border:1px solid var(--border);border-radius:12px}.card-grid header{display:flex;justify-content:space-between;gap:12px}.mode{display:flex;justify-content:space-between;margin:16px 0;padding:12px;border-radius:9px;background:var(--surface-muted)}.mode span{color:var(--text-secondary);font-size:12px}.card-grid dl{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.card-grid dt{color:var(--text-secondary);font-size:12px}.card-grid dd{margin:4px 0 0}.card-grid .el-progress{margin:16px 0 10px}.card-grid>article>.el-button{width:100%}.device{display:flex;gap:12px;align-items:center;margin:20px 0}.device svg{width:26px;color:var(--primary)}.device small{display:block;color:var(--text-secondary)}.unpaired{margin:20px 0;padding:15px;border:1px dashed var(--border);border-radius:10px;color:var(--text-secondary)}.card-grid footer{margin-top:18px}.attempts-head{align-items:flex-end}.filters{display:flex;gap:10px}.filters .el-select{width:150px}.attempt-list{padding:0 20px 20px}.attempt-list article{display:grid;grid-template-columns:1fr 120px 1.3fr;align-items:center;gap:16px;padding:14px 0;border-top:1px solid var(--border)}.empty{text-align:center;padding:30px;color:var(--text-secondary)}.policy-form{margin-top:18px}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:0 18px}.policy-form .el-input-number,.policy-form .el-date-editor{width:100%}.hint{color:var(--text-secondary)}
@media(max-width:900px){.overview-grid{grid-template-columns:1fr}.flow{grid-template-columns:repeat(2,1fr)}.health-row{grid-template-columns:38px 1fr auto}.quota{grid-column:2/4}}
@media(max-width:700px){.module-nav,.metrics,.card-grid{grid-template-columns:repeat(2,1fr)}.attempts-head{align-items:stretch}.attempt-list article{grid-template-columns:1fr auto}.result{grid-column:1/3}.form-grid{grid-template-columns:1fr}}
@media(max-width:480px){.metrics,.card-grid,.flow{grid-template-columns:1fr}.filters{flex-direction:column}.health-row{grid-template-columns:36px 1fr auto}.quota{grid-column:1/4}.health-row>.el-button{grid-column:1/4}.mode{align-items:flex-start;flex-direction:column;gap:5px}}
</style>
